const out=document.getElementById('out'),frame=document.getElementById('game');
document.getElementById('run').onclick=async()=>{out.textContent='';const win=frame.contentWindow,d=win.document,snap=()=>win.orbitSnapshot(),wait=ms=>new Promise(r=>setTimeout(r,ms)),check=(ok,msg)=>{out.textContent+=(ok?'PASS ':'FAIL ')+msg+'\n';if(!ok)throw Error(msg)},click=id=>d.getElementById(id).click(),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);try{click('reset');d.getElementById('reduce').checked=false;d.getElementById('reduce').dispatchEvent(new Event('change'));const original=snap();click('launch');await wait(900);check(snap().t>0,'비행 진행');d.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));let s=snap();check(s.state==='design'&&s.t===0&&s.vx===0&&s.omega===0,'Esc 비행 초기값 및 설계 복귀');check(same(s.design,original.design)&&same(s.planets,original.planets)&&same(s.storms,original.storms),'Esc 맵·우주선·폭풍 보존');check(!d.getElementById('launch').disabled,'설계·발사 활성화');click('launch');await wait(400);click('retry');s=snap();check(s.state==='design'&&same(s.planets,original.planets)&&same(s.design,original.design),'버튼으로 같은 맵·설계 복귀');const vt=s.visualTime;for(let i=0;i<20&&snap().visualTime<=vt;i++)await wait(250);check(snap().visualTime>vt,'폭풍 애니메이션 시간 진행');click('reduce');const still=snap().visualTime;await wait(350);check(snap().visualTime===still,'효과 줄이기 애니메이션 정지');click('launch');click('reset');s=snap();check(s.state==='design'&&s.t===0&&s.launches===0&&s.wins===0&&!same(s.planets,original.planets),'비행 중 초기화 새 맵·기록 0');check(same(s.design,win.Orbit.example()),'초기화 기본 설계');check(d.getElementById('retry').parentElement===d.getElementById('reset').parentElement,'두 버튼 나란히 배치');}catch(e){out.textContent+='ERROR '+e.message;}};
